"use client"

import React, { useState } from "react"
import { Link, cn } from "@heroui/react"
import { SealCheckIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import { pathConfig } from "@/resources/path"
import { EntityLink } from "@/components/blocks/feed/EntityLink"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import { ReactionBar } from "./ReactionBar"
import { CommentComposer } from "./CommentComposer"
import { ReactionType, type CommentNode } from "@/modules/api/graphql/queries/types/discussion"
/** Callbacks shared down the comment tree. */
export interface CommentItemCallbacks {
    /** Post a reply under `parentId`. */
    onReply: (parentId: string, body: string) => void
    /** Edit a comment body (author only). */
    onEdit: (commentId: string, body: string) => void
    /** Soft-delete a comment (author only). */
    onDelete: (commentId: string) => void
    /** React to a comment (null removes the reaction). */
    onReactComment: (commentId: string, type: ReactionType | null) => void
    /** Lazily load the replies of `parentId`. */
    onLoadReplies: (parentId: string) => void
}

/** Props for {@link CommentItem}. */
export interface CommentItemProps extends CommentItemCallbacks {
    /** The comment to render. */
    comment: CommentNode
    /** Current viewer id (drives owner-only actions); null when unknown. */
    currentUserId: string | null
    /** Nesting depth (controls visual indentation). */
    depth: number
    /** Replies keyed by parent comment id (lazily populated by the container). */
    repliesByParent: Record<string, Array<CommentNode>>
}

/**
 * A single threaded comment with author, reactions, owner actions, reply box, and its
 * recursively-rendered replies. Visual indentation is capped so deep threads stay readable.
 *
 * Presentational: owns only transient UI state (editing/replying/expanded); persistence is
 * delegated via the {@link CommentItemCallbacks}.
 * @param props - {@link CommentItemProps}
 */
export const CommentItem = ({
    comment,
    currentUserId,
    depth,
    repliesByParent,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies}: CommentItemProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // transient per-comment UI state
    const [replying, setReplying] = useState(false)
    const [editing, setEditing] = useState(false)
    const [expanded, setExpanded] = useState(false)

    const isOwner = currentUserId !== null && currentUserId === comment.author.id
    const replies = repliesByParent[comment.id] ?? []

    // expand/collapse the reply subtree, loading it on first expand
    const toggleReplies = () => {
        const next = !expanded
        setExpanded(next)
        if (next) {
            onLoadReplies(comment.id)
        }
    }

    return (
        <div
            className={cn("flex flex-col gap-2",
                // indent nested replies with a guide border, capped after a few levels
                depth > 0 ? "border-l border-default pl-3 @app-sm:pl-4" : undefined)}
        >
            <div className="flex gap-3">
                <UserAvatar
                    size="sm"
                    username={comment.author.username}
                    avatar={comment.author.avatar}
                    className="mt-0 shrink-0"
                />
                <div className="flex min-w-0 flex-1 flex-col gap-2">
                    {/* author + founder badge + timestamp header */}
                    <div className="flex flex-wrap items-center gap-2">
                        <EntityLink
                            label={comment.author.username}
                            onPress={() => router.push(
                                pathConfig().locale(locale).profile(comment.author.username).build(),
                            )}
                        />
                        {comment.isFounderAuthor ? (
                            <SealCheckIcon
                                weight="fill"
                                aria-label={t("discussion.founderBadge")}
                                className="size-3.5 shrink-0 text-accent-soft-foreground"
                            />
                        ) : null}
                        <span className="text-xs text-muted">
                            {getTimeAgoLabel(getTimeAgoMessage(comment.createdAt), t)}
                        </span>
                        {comment.editedAt ? (
                            <span className="text-xs text-muted">{t("discussion.edited")}</span>
                        ) : null}
                    </div>

                    {/* body, edit form, or deleted placeholder */}
                    {comment.isDeleted ? (
                        <div className="text-sm italic text-muted">{t("discussion.deletedPlaceholder")}</div>
                    ) : editing ? (
                        <CommentComposer
                            initialValue={comment.body}
                            submitLabel={t("common.save")}
                            onCancel={() => setEditing(false)}
                            onSubmit={(body) => {
                                onEdit(comment.id, body)
                                setEditing(false)
                            }}
                        />
                    ) : (
                        <div className="whitespace-pre-wrap text-sm leading-relaxed text-foreground">
                            {comment.body}
                        </div>
                    )}

                    {/* action row: reactions + reply + owner edit/delete */}
                    {!comment.isDeleted && !editing ? (
                        <div className="flex flex-wrap items-center gap-3">
                            <ReactionBar
                                summary={comment.reactions}
                                onReact={(type) => onReactComment(comment.id, type)}
                            />
                            <Link
                                className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                                onPress={() => setReplying((prev) => !prev)}
                            >
                                {t("discussion.reply")}
                            </Link>
                            {isOwner ? (
                                <>
                                    <Link
                                        className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                                        onPress={() => setEditing(true)}
                                    >
                                        {t("common.edit")}
                                    </Link>
                                    <Link
                                        className="cursor-pointer text-xs font-medium text-muted hover:text-danger-soft-foreground"
                                        onPress={() => onDelete(comment.id)}
                                    >
                                        {t("common.delete")}
                                    </Link>
                                </>
                            ) : null}
                        </div>
                    ) : null}

                    {/* reply composer */}
                    {replying ? (
                        <CommentComposer
                            placeholder={t("discussion.replyPlaceholder")}
                            submitLabel={t("discussion.reply")}
                            onCancel={() => setReplying(false)}
                            onSubmit={(body) => {
                                onReply(comment.id, body)
                                setReplying(false)
                                // surface the new reply immediately by expanding the subtree
                                setExpanded(true)
                                onLoadReplies(comment.id)
                            }}
                        />
                    ) : null}

                    {/* replies toggle + recursive subtree */}
                    {comment.replyCount > 0 ? (
                        <Link
                            className="cursor-pointer self-start text-xs font-medium text-accent-soft-foreground hover:underline underline-offset-4 decoration-[var(--separator-tertiary)]"
                            onPress={toggleReplies}
                        >
                            {expanded
                                ? t("discussion.hideReplies")
                                : t("discussion.viewReplies", { count: comment.replyCount })}
                        </Link>
                    ) : null}

                    {expanded && replies.length > 0 ? (
                        <div className="mt-1 flex flex-col gap-3">
                            {replies.map((reply) => (
                                <CommentItem
                                    key={reply.id}
                                    comment={reply}
                                    currentUserId={currentUserId}
                                    depth={depth + 1}
                                    repliesByParent={repliesByParent}
                                    onReply={onReply}
                                    onEdit={onEdit}
                                    onDelete={onDelete}
                                    onReactComment={onReactComment}
                                    onLoadReplies={onLoadReplies}
                                />
                            ))}
                        </div>
                    ) : null}
                </div>
            </div>
        </div>
    )
}

"use client"

import React from "react"
import { cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { REACTIONS } from "./constants"
import { ReactionEmoji } from "./ReactionEmoji"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"

/** Props for {@link FacebookReactionSelector}. */
export interface FacebookReactionSelectorProps {
    /** The viewer's current reaction, highlighted in the bar (null = none). */
    active?: ReactionType | null
    /** Called with the picked emotion. */
    onSelect: (type: ReactionType) => void
}

/**
 * Facebook-style reaction picker bar — the six emotions in a row, each scaling up and
 * lifting with its name floating above on hover, popping in with a slight stagger when
 * the bar appears.
 *
 * Reimplemented natively (native emoji glyphs + CSS keyframe `reactionPop`, NO third-party
 * reaction library) so it follows our design tokens + dark mode. The pop-in animation sits
 * on the button while the hover scale sits on an inner span, so the two transforms never
 * clash. Render inside the reaction Popover; selection is delegated via `onSelect`.
 *
 * @param props - {@link FacebookReactionSelectorProps}
 */
export const FacebookReactionSelector = ({ active, onSelect}: FacebookReactionSelectorProps) => {
    const t = useTranslations()

    return (
        <div className={"flex items-center gap-1"}>
            {REACTIONS.map((reaction, index) => {
                const label = t(reaction.labelKey)
                return (
                    <button
                        key={reaction.type}
                        type="button"
                        aria-label={label}
                        aria-pressed={active === reaction.type}
                        onClick={() => onSelect(reaction.type)}
                        // each emoji bounces in slightly after the previous one
                        style={{ animationDelay: `${index * 35}ms` }}
                        className={cn(
                            "group/fbreact relative flex animate-[reactionPop_220ms_cubic-bezier(0.34,1.56,0.64,1)_both]",
                            "cursor-pointer items-center justify-center rounded-full p-1 outline-none",
                            "focus-visible:ring-2 focus-visible:ring-accent",
                            active === reaction.type ? "bg-accent-soft" : undefined,
                        )}
                    >
                        {/* reaction name floats above on hover, in the style of Facebook */}
                        <span className="pointer-events-none absolute -top-7 left-1/2 -translate-x-1/2 scale-90 whitespace-nowrap rounded-full bg-foreground px-2 py-0 text-[10px] font-medium text-background opacity-0 transition-all duration-150 group-hover/fbreact:scale-100 group-hover/fbreact:opacity-100">
                            {label}
                        </span>
                        {/* emoji scales up + lifts on hover (transform isolated from the pop-in) */}
                        <span className="block origin-bottom transition-transform duration-150 ease-out group-hover/fbreact:-translate-y-1 group-hover/fbreact:scale-[1.45]">
                            <ReactionEmoji descriptor={reaction} size="md" />
                        </span>
                    </button>
                )
            })}
        </div>
    )
}

"use client"

import { EyeIcon } from "@phosphor-icons/react"
import React from "react"
import { ReactionBar } from "./ReactionBar"
import { ReactionType, type ReactionSummary } from "@/modules/api/graphql/queries/types/discussion"

/** Props for {@link InteractionBar}. */
export interface InteractionBarProps {
    /** Aggregate reaction summary for the content. */
    summary: ReactionSummary | undefined
    /** React to / un-react from the content (null removes the reaction). */
    onReact: (type: ReactionType | null) => void
    /** Optional view count from the server (undefined = not tracked yet). */
    viewCount?: number
}

/**
 * Single-row content interaction: the shared {@link ReactionBar} (HeroUI Button trigger +
 * emoji picker + summary) on the left — IDENTICAL to each comment's reaction — and the
 * view count on the right. Save / share / fullscreen are intentionally NOT here — they own
 * a single home in the OnThisPage rail.
 */
export const InteractionBar = ({
    summary,
    onReact,
    viewCount,
}: InteractionBarProps) => {
    return (
        <div className="flex items-center justify-between gap-3">
            {/* reaction trigger + summary — same control as the comment reactions */}
            <ReactionBar summary={summary} onReact={onReact} />

            {/* view count */}
            {viewCount !== undefined ? (
                <span className="flex items-center gap-2 text-xs text-muted">
                    <EyeIcon aria-hidden focusable="false" className="size-4" />
                    {viewCount.toLocaleString()}
                </span>
            ) : null}
        </div>
    )
}

"use client"

import React, { useState } from "react"
import { Button, Popover } from "@heroui/react"
import { useTranslations } from "next-intl"
import { REACTION_BY_TYPE } from "./constants"
import { ReactionEmoji } from "./ReactionEmoji"
import { FacebookReactionSelector } from "./FacebookReactionSelector"
import { ReactionType, type ReactionSummary } from "@/modules/api/graphql/queries/types/discussion"

/** Props for {@link ReactionBar}. */
export interface ReactionBarProps {
    /** Current reaction summary for the target (content or comment). */
    summary: ReactionSummary | undefined
    /** Called with a new emotion, or null to remove the current one. */
    onReact: (type: ReactionType | null) => void
    /** Disables interaction (e.g. while a mutation is in flight). */
    disabled?: boolean
}

/**
 * Facebook-style reaction control: a HeroUI Button trigger that opens a 6-emoji picker
 * (HeroUI Popover), plus a compact summary (top emojis + total). Picking the active
 * emotion again removes it. The SAME control is used for both the content reaction
 * (InteractionBar) and each comment, so they render identically.
 *
 * Presentational: only local picker-open state; all persistence is delegated via `onReact`.
 * @param props - {@link ReactionBarProps}
 */
export const ReactionBar = ({ summary, onReact, disabled}: ReactionBarProps) => {
    const t = useTranslations()
    // controlled so the popover closes as soon as an emotion is picked
    const [open, setOpen] = useState(false)
    const myReaction = summary?.myReaction ?? null
    const total = summary?.total ?? 0
    // emotions present on the target, busiest first, capped to the top 3 descriptors
    const topReactions = (summary?.counts ?? [])
        .slice()
        .sort((prev, next) => next.count - prev.count)
        .slice(0, 3)
        .map((count) => REACTION_BY_TYPE[count.type])
        .filter(Boolean)

    const myDescriptor = myReaction ? REACTION_BY_TYPE[myReaction] : REACTION_BY_TYPE[ReactionType.Like]

    // picking an emotion toggles it off when it's already the user's pick, then closes
    const onPick = (type: ReactionType) => {
        setOpen(false)
        onReact(myReaction === type ? null : type)
    }

    return (
        <div className={"flex items-center gap-2"}>
            {/* trigger: a real HeroUI Button (pill); secondary once the viewer has reacted */}
            <Popover isOpen={open} onOpenChange={setOpen}>
                <Popover.Trigger>
                    <Button
                        size="sm"
                        variant={myReaction ? "secondary" : "tertiary"}
                        isDisabled={disabled}
                        className="rounded-full"
                    >
                        <ReactionEmoji descriptor={myDescriptor} size="xs" />
                        <span className="text-xs">
                            {myReaction
                                ? t(REACTION_BY_TYPE[myReaction].labelKey)
                                : t("discussion.react")}
                        </span>
                    </Button>
                </Popover.Trigger>
                <Popover.Content className="overflow-visible rounded-full px-2 py-1">
                    <FacebookReactionSelector active={myReaction} onSelect={onPick} />
                </Popover.Content>
            </Popover>

            {/* compact summary: stacked top emojis + total count */}
            {total > 0 ? (
                <div className="flex items-center gap-2 text-xs text-muted">
                    <span className="flex items-center -space-x-1">
                        {topReactions.map((reaction) => (
                            <ReactionEmoji key={reaction.type} descriptor={reaction} size="xs" />
                        ))}
                    </span>
                    <span>{total}</span>
                </div>
            ) : null}
        </div>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"

/** Props for the {@link ActivityAvatar} block. */
export interface ActivityAvatarProps {
    /** Main avatar's username — drives the image / initials fallback. */
    username: string
    /** Uploaded avatar URL (a generated default is used when missing). */
    avatar?: string | null
    /** Activity-type icon (phosphor `*Icon`) shown in the soft-accent badge. */
    icon: ReactNode
}

/**
 * Facebook-style feed avatar: a {@link UserAvatar} with a small activity-type icon
 * badge at the bottom-right. The badge is an OPAQUE soft-accent disc (a `bg-surface`
 * base under a `bg-accent-soft` tint so the avatar never bleeds through) with an
 * accent icon, and a surface ring cuts it cleanly from the avatar. The owning
 * feature decides whose avatar is the main one (e.g. the followed user on a
 * "followed" event). Pure/props-only; owns its look.
 *
 * @param props - {@link ActivityAvatarProps}
 */
export const ActivityAvatar = ({
    username,
    avatar,
    icon}: ActivityAvatarProps) => {
    return (
        <div className={"relative shrink-0"}>
            <UserAvatar
                className="size-9"
                username={username}
                avatar={avatar ?? undefined}
                seed={username}
            />
            <span
                aria-hidden
                className="absolute -bottom-1 -right-1 flex size-5 items-center justify-center rounded-full bg-surface ring-2 ring-surface"
            >
                <span className="flex size-full items-center justify-center rounded-full bg-accent-soft text-accent-soft-foreground [&_svg]:size-3">
                    {icon}
                </span>
            </span>
        </div>
    )
}

"use client"

import React from "react"
import { cn } from "@heroui/react"
import type { ReactNode } from "react"

/** Who authored a chat message. */
export type ChatRole = "user" | "assistant"

/** Props for the {@link ChatBubble} block. */
export interface ChatBubbleProps {
    /** Author of the message — drives alignment + tint. */
    role: ChatRole
    /** Message content (text or a markdown render). */
    children: ReactNode
}

/**
 * A single chat message bubble: user messages align right with an accent tint,
 * assistant messages align left on the surface tint. Pure + props-only; owns its
 * look so chat features only compose it.
 *
 * @param props - {@link ChatBubbleProps}
 */
export const ChatBubble = ({ role, children}: ChatBubbleProps) => {
    const isUser = role === "user"
    return (
        <div className={cn("flex", isUser ? "justify-end" : "justify-start")}>
            <div
                className={cn(
                    "max-w-[85%] rounded-2xl px-3 py-2",
                    isUser ? "bg-accent-soft" : "bg-surface-secondary",
                )}
            >
                {children}
            </div>
        </div>
    )
}

"use client"

import React, { useEffect, useRef } from "react"
import { cn } from "@heroui/react"
import { ChatBubble } from "@/components/blocks/feed/ChatBubble"
import { Composer } from "@/components/blocks/feed/Composer"
import type { ComposerProps } from "@/components/blocks/feed/Composer"

/** One message rendered by {@link ChatPanel}. */
export interface ChatPanelMessage {
    /** Stable id — used as the React key. */
    id: string
    /** Author of the message — maps to the {@link ChatBubble} alignment + tint. */
    role: "user" | "assistant"
    /** Message body (text or a markdown render), rendered inside the bubble. */
    content: React.ReactNode
    /**
     * Optional tool-result row rendered below the bubble, assistant-aligned — e.g. a
     * {@link import("@/components/blocks/learn/ChatToolResult").ChatToolResult}. The
     * caller builds it; the panel only places it.
     */
    toolResult?: React.ReactNode
}

/**
 * Props for the {@link ChatPanel} block.
 *
 * A full chat surface: a scrollable message list, an optional typing indicator, an
 * empty-state slot, and a sticky-bottom {@link Composer}. Tier-3 presentational —
 * all data + the composer wiring arrive via props; the only side-effect is an
 * auto-scroll-to-bottom effect on the list ref.
 */
export interface ChatPanelProps {
    /** The conversation, oldest first. Each entry renders one {@link ChatBubble}. */
    messages: Array<ChatPanelMessage>
    /** Props forwarded to the sticky-bottom {@link Composer} (controlled by the parent). */
    composer: ComposerProps
    /** When true, a three-dot typing indicator shows below the last message. */
    isTyping?: boolean
    /** Rendered centered in the list area when there are no messages. */
    emptyState?: React.ReactNode
}

/**
 * ChatPanel assembles the existing feed primitives into a complete chat surface:
 * a scrollable list of {@link ChatBubble}s (with optional tool-result rows
 * interleaved under assistant turns), an optional animated typing indicator, an
 * empty-state slot when the conversation is empty, and a sticky-bottom
 * {@link Composer} for the next message. The list auto-scrolls to the newest turn
 * whenever the messages or typing state change.
 *
 * Tier-3 presentational block: props-only, no store, no SWR. The parent owns the
 * message data and the composer's controlled draft.
 *
 * @param props - {@link ChatPanelProps}
 *
 * @example
 * <ChatPanel
 *   messages={turns}
 *   composer={{ value: draft, onChange: setDraft, onSubmit: send }}
 *   isTyping={isThinking}
 * />
 * @see Story: .storybook/stories/blocks/feed/ChatPanel/ChatPanel.stories
 */
export const ChatPanel = ({
    messages,
    composer,
    isTyping = false,
    emptyState}: ChatPanelProps) => {
    const listRef = useRef<HTMLDivElement>(null)

    // keep the newest turn in view as the conversation (or typing state) grows
    useEffect(() => {
        const element = listRef.current
        if (!element) {
            return
        }
        element.scrollTop = element.scrollHeight
    }, [messages, isTyping])

    const isEmpty = messages.length === 0

    return (
        <div
            className={cn("flex flex-col overflow-hidden rounded-3xl border border-default bg-surface",
                "h-[32rem]")}
        >
            {/* scrollable message list */}
            <div ref={listRef} className="flex-1 overflow-y-auto p-4">
                {isEmpty ? (
                    <div className="flex h-full items-center justify-center">
                        {emptyState}
                    </div>
                ) : (
                    <div className="flex flex-col gap-3">
                        {messages.map((message) => (
                            <div key={message.id} className="flex flex-col gap-2">
                                <ChatBubble role={message.role}>
                                    {message.content}
                                </ChatBubble>
                                {/* optional tool-result row, assistant-aligned under the bubble */}
                                {message.toolResult ? (
                                    <div className="flex justify-start">
                                        <div className="w-full max-w-[85%]">
                                            {message.toolResult}
                                        </div>
                                    </div>
                                ) : null}
                            </div>
                        ))}

                        {/* three-dot typing indicator on the assistant side */}
                        {isTyping ? (
                            <div className="flex justify-start">
                                <div className="flex items-center gap-1 rounded-2xl bg-surface-secondary px-3 py-3">
                                    {[0, 1, 2].map((dot) => (
                                        <span
                                            key={dot}
                                            className="size-1.5 animate-bounce rounded-full bg-muted"
                                            style={{ animationDelay: `${dot * 0.15}s` }}
                                        />
                                    ))}
                                </div>
                            </div>
                        ) : null}
                    </div>
                )}
            </div>

            {/* sticky-bottom composer */}
            <div className="border-t border-default p-3">
                <Composer {...composer} />
            </div>
        </div>
    )
}

"use client"

import React, {
    useEffect,
    useRef,
    useState,
} from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import {
    SmileyIcon,
} from "@phosphor-icons/react"
import {
    AnimatePresence,
    motion,
} from "framer-motion"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"

/** The six reactions + their emoji glyph, in display order. */
const REACTIONS: ReadonlyArray<{ type: ReactionType, emoji: string }> = [
    { type: ReactionType.Like, emoji: "👍" },
    { type: ReactionType.Love, emoji: "❤️" },
    { type: ReactionType.Haha, emoji: "😄" },
    { type: ReactionType.Wow, emoji: "😮" },
    { type: ReactionType.Sad, emoji: "😢" },
    { type: ReactionType.Angry, emoji: "😠" },
]

/** Emoji glyph by reaction type. */
const EMOJI: Record<ReactionType, string> = REACTIONS.reduce(
    (acc, reaction) => {
        acc[reaction.type] = reaction.emoji
        return acc
    },
    {} as Record<ReactionType, string>,
)

/** Springy pop for the picker container; staggers its emoji children in. */
const PICKER_VARIANTS = {
    hidden: { opacity: 0, y: 8, scale: 0.8 },
    visible: {
        opacity: 1,
        y: 0,
        scale: 1,
        transition: { type: "spring", stiffness: 500, damping: 30, staggerChildren: 0.03 },
    },
    exit: { opacity: 0, y: 8, scale: 0.8, transition: { duration: 0.12 } },
} as const

/** Each emoji rises + scales in as the picker opens. */
const EMOJI_VARIANTS = {
    hidden: { opacity: 0, y: 6, scale: 0.5 },
    visible: { opacity: 1, y: 0, scale: 1 },
} as const

/** Props for the {@link ReactionBar} block. */
export interface ReactionBarProps {
    /** Total reactions on the target. */
    count: number
    /** The viewer's own reaction, or null. */
    myReaction: ReactionType | null
    /**
     * React handler — pass the chosen emotion, or `null` to remove. **Omit to make
     * the bar READ-ONLY** (count display only, no picker) — used when the viewer
     * may not react (e.g. their own activity, or anonymous).
     */
    onReact?: (type: ReactionType | null) => void
}

/**
 * Facebook-style reaction bar for a feed item: a react trigger (the viewer's
 * current emoji, or a neutral smiley) that pops a 6-emoji picker, beside the total
 * count. Tapping the same emotion removes it; tapping another switches. When
 * `onReact` is omitted the bar is READ-ONLY — it shows just the count (+ the
 * viewer's emoji) and renders nothing when there are no reactions.
 *
 * Animation is pure `framer-motion` (no third-party emoji asset): the picker
 * springs up + staggers its emoji in, each emoji scales/lifts on hover and
 * squashes on tap, and the trigger emoji pops when the viewer's reaction changes.
 * Pure block: owns its look + the local picker-open state; the owning feature
 * supplies data + the react handler.
 *
 * @param props - {@link ReactionBarProps}
 * @see Story: .storybook/stories/blocks/feed/ReactionBar/ReactionBar.stories
 */
export const ReactionBar = ({
    count,
    myReaction,
    onReact}: ReactionBarProps) => {
    const [open, setOpen] = useState(false)
    const rootRef = useRef<HTMLDivElement>(null)

    // close the picker when clicking anywhere outside the bar
    useEffect(() => {
        if (!open) {
            return
        }
        const onPointerDown = (event: PointerEvent) => {
            if (rootRef.current && !rootRef.current.contains(event.target as Node)) {
                setOpen(false)
            }
        }
        document.addEventListener("pointerdown", onPointerDown)
        return () => document.removeEventListener("pointerdown", onPointerDown)
    }, [open])

    // close the picker on Escape, from anywhere within the bar
    useEffect(() => {
        if (!open) {
            return
        }
        const onKeyDown = (event: KeyboardEvent) => {
            if (event.key === "Escape") {
                setOpen(false)
            }
        }
        document.addEventListener("keydown", onKeyDown)
        return () => document.removeEventListener("keydown", onKeyDown)
    }, [open])

    // read-only: count + the viewer's emoji; nothing when there are no reactions
    if (!onReact) {
        if (count <= 0) {
            return null
        }
        return (
            <div className={"flex items-center gap-1"}>
                {myReaction ? <span aria-hidden>{EMOJI[myReaction]}</span> : null}
                <Typography type="body-xs" color="muted">{count}</Typography>
            </div>
        )
    }

    /** Pick (or toggle off) an emotion, then close the picker. */
    const pick = (type: ReactionType) => {
        onReact(myReaction === type ? null : type)
        setOpen(false)
    }

    return (
        <div
            ref={rootRef}
            className={"relative flex items-center gap-2"}
        >
            <button
                type="button"
                aria-label="React"
                aria-expanded={open}
                onClick={() => setOpen((previous) => !previous)}
                className="flex items-center gap-1 rounded-full px-2 py-0 text-muted transition-colors hover:bg-default/40 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent"
            >
                <AnimatePresence mode="popLayout" initial={false}>
                    {myReaction ? (
                        <motion.span
                            key={myReaction}
                            aria-hidden
                            className="text-sm leading-none"
                            initial={{ scale: 0, rotate: -30 }}
                            animate={{ scale: 1, rotate: 0 }}
                            exit={{ scale: 0, rotate: 30 }}
                            transition={{ type: "spring", stiffness: 600, damping: 20 }}
                        >
                            {EMOJI[myReaction]}
                        </motion.span>
                    ) : (
                        <motion.span
                            key="placeholder"
                            initial={{ scale: 0.6 }}
                            animate={{ scale: 1 }}
                            className="flex"
                        >
                            <SmileyIcon aria-hidden focusable="false" className="size-4" />
                        </motion.span>
                    )}
                </AnimatePresence>
                {count > 0 ? (
                    <Typography type="body-xs" className={cn(myReaction ? "text-accent-soft-foreground" : "text-muted")}>
                        {count}
                    </Typography>
                ) : null}
            </button>

            <AnimatePresence>
                {open ? (
                    <motion.div
                        variants={PICKER_VARIANTS}
                        initial="hidden"
                        animate="visible"
                        exit="exit"
                        style={{ transformOrigin: "bottom left" }}
                        className="absolute bottom-full left-0 z-10 mb-1 flex items-center gap-1 rounded-full bg-surface p-1 ring-1 ring-separator"
                    >
                        {REACTIONS.map((reaction) => (
                            <motion.button
                                key={reaction.type}
                                type="button"
                                aria-label={reaction.type}
                                variants={EMOJI_VARIANTS}
                                whileHover={{ scale: 1.4, y: -4 }}
                                whileTap={{ scale: 0.85 }}
                                transition={{ type: "spring", stiffness: 500, damping: 18 }}
                                onClick={() => pick(reaction.type)}
                                className={cn(
                                    "flex size-7 items-center justify-center rounded-full text-base leading-none focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent",
                                    myReaction === reaction.type && "bg-accent-soft",
                                )}
                            >
                                <span aria-hidden>{reaction.emoji}</span>
                            </motion.button>
                        ))}
                    </motion.div>
                ) : null}
            </AnimatePresence>
        </div>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { cn } from "@heroui/react"

/** Props for {@link Timeline}. */
export interface TimelineProps {
